import Foundation

/// An area an offline routing pack can be downloaded for, mirroring the Android `PackRegion`. Each pack is built on GitHub
/// from the Geofabrik extract of OpenStreetMap and published as a release called "pack-<id>".
struct PackRegion: Identifiable, Hashable {
    let id: String
    let name: String
    let group: String
    let country: String
    var parent: String = ""

    /// The original UK packs live in the HeadUnitOrbis repository; every other area is built in Horizon-Maps.
    var url: URL {
        let base = id == "ew" || id == "gb"
            ? "https://github.com/benbishop028-arch/HeadUnitOrbis/releases/download"
            : "https://github.com/benbishop028-arch/Horizon-Maps/releases/download"
        return URL(string: "\(base)/pack-\(id)")!
    }

    /// Where the speed camera file is: the same release, except the UK packs, whose extras are built in Horizon-Maps.
    var extrasURL: URL { URL(string: "https://github.com/benbishop028-arch/Horizon-Maps/releases/download/pack-\(id)")! }
}

